  if (t.sliding > 0) return { x: t.x - 34, y: t.y - 34, w: 78, h: 34 };
  return { x: t.x - 30, y: t.y - 72, w: 62, h: 72 };
}

export function turkeyJump(t, sounds) {
  if (t.sliding > 0) return;
